mapper.select:
select t.* from ( SELECT a.*, hsno.read_flag as read_flag, hsno.done_flag as done_flag, su.description as source_user_name, (case when hsno.read_flag='Y' then '已读' else '未读' end ) read_flag_n, concat(a.notice_message,a.notice_title) notice_information FROM hls_system_notice a LEFT JOIN hls_system_notice_owner hsno ON hsno.owner_allocation_id = #{allocation_id,jdbcType=BIGINT} and hsno.notice_id=a.NOTICE_ID ,sys_user su
a.SOURCE_USER_ID = su.USER_ID and (( a.NOTICE_LEVEL = 1 AND a.SOURCE_ALLOCATION_ID = #{allocation_id,jdbcType=BIGINT} ) OR (a.NOTICE_LEVEL = 3) OR (a.NOTICE_LEVEL = 2 AND a.SOURCE_ALLOCATION_ID = #{allocation_id,jdbcType=BIGINT}))
and a.NOTICE_TYPE =#{dto.noticeType}
and a.NOTICE_ID =#{dto.noticeId}
and a.NOTICE_MESSAGE like concat(concat('%',#{dto.noticeMessage}),'%')
and 1 = (case when #{dto.readFlag}='Y' and hsno.read_flag='Y' then 1 when #{dto.readFlag}='N' and (hsno.read_flag='N' or hsno.read_flag is null or hsno.read_flag='') then 1 else 0 end)
order by a.notice_datetime desc) t
and t.notice_information like concat(concat('%',#{dto.noticeInformation}),'%')
and t.read_flag_n =#{dto.readFlagN}

mapper.update:
UPDATE HLS_SYSTEM_NOTICE_OWNER t1
SET t1.read_flag = 'Y'
WHERE t1.OWNER_ALLOCATION_ID = #{allocation_id,jdbcType=BIGINT}

mapper.select:
select (SELECT count(*) FROM hls_system_notice a LEFT JOIN hls_system_notice_owner hsno ON hsno.owner_allocation_id = #{allocation_id,jdbcType=BIGINT} and hsno.notice_id=a.NOTICE_ID a.notice_type = 'NOTICE' and ((a.NOTICE_LEVEL = 1 AND a.SOURCE_ALLOCATION_ID = #{allocation_id,jdbcType=BIGINT}) OR (a.NOTICE_LEVEL = 3) OR (a.NOTICE_LEVEL = 2 AND a.SOURCE_ALLOCATION_ID = #{allocation_id,jdbcType=BIGINT}) ) and (hsno.read_flag='N' or hsno.read_flag is null or hsno.read_flag='')
and a.NOTICE_ID =#{dto.noticeId}
and a.NOTICE_MESSAGE like concat(concat('%',#{dto.noticeMessage}),'%')
) as notice_count, (SELECT count(*) FROM hls_system_notice a left JOIN hls_system_notice_owner hsno ON hsno.owner_allocation_id = #{allocation_id,jdbcType=BIGINT} and hsno.notice_id = a.NOTICE_ID a.notice_type = 'TODO' and (hsno.done_flag = 'N' or hsno.done_flag is null) and a.SOURCE_DOCUMENT_ID in ( select distinct t1.ID_ from act_ru_task t1 ) and ((a.NOTICE_LEVEL = 1 AND a.SOURCE_ALLOCATION_ID = #{allocation_id,jdbcType=BIGINT}) OR (a.NOTICE_LEVEL = 3) OR (a.NOTICE_LEVEL = 2 AND a.SOURCE_ALLOCATION_ID = #{allocation_id,jdbcType=BIGINT})
and a.NOTICE_ID =#{dto.noticeId}
and a.NOTICE_MESSAGE like concat(concat('%',#{dto.noticeMessage}),'%')
)
) as todo_count from dual

SELECT hls.NOTICE_ID as noticeId, hls.NOTICE_MESSAGE as message, hls.NOTICE_DATETIME as dateTime, hls.SOURCE_MODULE as documentType, hls.SOURCE_DOCUMENT_ID as documentId, hls.SOURCE_EVENT as eventCode, hls.SOURCE_DOCUMENT_CATEGORY as category FROM hls_system_notice hls WHERE hls.NOTICE_TYPE='NOTICE' AND hls.SOURCE_DOCUMENT_CATEGORY='PRJ_PROJECT' AND hls.SOURCE_DOCUMENT_ID=(select chance_id from prj_project where project_id = #{projectId}) UNION SELECT hls.NOTICE_ID as noticeId, hls.NOTICE_MESSAGE as message, hls.NOTICE_DATETIME as dateTime, hls.SOURCE_MODULE as documentType, hls.SOURCE_DOCUMENT_ID as documentId, hls.SOURCE_EVENT as eventCode, hls.SOURCE_DOCUMENT_CATEGORY as category FROM hls_system_notice hls WHERE hls.NOTICE_TYPE='NOTICE' AND hls.SOURCE_DOCUMENT_CATEGORY='CONTRACT_COMPLETE' AND hls.SOURCE_DOCUMENT_ID in(
select cct.contract_termination_id from con_contract_termination cct where cct.contract_id = #{contractId}
select cct.contract_termination_id from con_contract_termination cct where cct.contract_id in ( SELECT cc.contract_id FROM con_contract cc WHERE cc.project_id=#{projectId} )
)

SELECT hls.NOTICE_ID as noticeId, hls.NOTICE_MESSAGE as message, hls.NOTICE_DATETIME as dateTime, hls.SOURCE_MODULE as documentType, hls.SOURCE_DOCUMENT_ID as documentId, hls.SOURCE_EVENT as eventCode, hls.SOURCE_DOCUMENT_CATEGORY as category FROM hls_system_notice hls WHERE hls.NOTICE_TYPE='NOTICE' AND hls.SOURCE_DOCUMENT_CATEGORY='CONTRACT_INCEPT' AND hls.SOURCE_DOCUMENT_ID in(
select cci.CONTRACT_INCEPT_REQ_ID from con_contract_incept cci where cci.contract_incept_id = #{inceptId}
0
) order by hls.NOTICE_DATETIME asc
